<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staywise — Hotel bookings</title>@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="bg-slate-50 text-slate-900"><header class="bg-white"><nav class="mx-auto flex max-w-6xl justify-between px-6 py-5"><a class="text-2xl font-black text-emerald-800" href="/">Staywise</a><div class="flex gap-5"><a href="/login">Sign in</a><a href="/register">Create account</a></div></nav></header><main class="mx-auto max-w-6xl px-6 py-14"><p class="font-semibold uppercase tracking-widest text-emerald-700">Thoughtful stays, made simple</p><h1 class="mt-3 max-w-3xl text-5xl font-bold">Find a room for the trip you’ve been planning.</h1><p class="mt-4 max-w-2xl text-lg text-slate-600">Search independent hotels by destination and dates. Clear prices, confirmed availability, no surprises.</p><form class="mt-9 grid gap-4 rounded-2xl bg-white p-5 shadow-sm md:grid-cols-4" action="/" method="GET"><label>City<input class="mt-1 w-full rounded border p-3" name="city" placeholder="Where to?" value="{{ request('city') }}"></label><label>Check-in<input class="mt-1 w-full rounded border p-3" type="date" name="check_in" value="{{ request('check_in') }}"></label><label>Check-out<input class="mt-1 w-full rounded border p-3" type="date" name="check_out" value="{{ request('check_out') }}"></label><label>Guests<input class="mt-1 w-full rounded border p-3" type="number" min="1" name="guests" value="{{ request('guests',1) }}"></label><button class="rounded bg-emerald-800 px-5 py-3 font-bold text-white md:col-span-4">Search available stays</button></form><section class="mt-12 grid gap-5 md:grid-cols-3">@forelse($rooms ?? [] as $room)<article class="rounded-xl border bg-white p-6"><p class="text-sm font-semibold text-emerald-700">{{ $room->hotel->city }} · Sleeps {{ $room->capacity }}</p><h2 class="mt-2 text-xl font-bold">{{ $room->hotel->name }} — {{ $room->name }}</h2><p class="mt-2 text-slate-600">{{ $room->description }}</p><p class="mt-4 font-bold">${{ number_format($room->nightly_rate_minor / 100,2) }} / night</p>@auth<form method="POST" action="{{ route('bookings.store',$room) }}" class="mt-4 grid gap-2">@csrf<input required type="date" name="check_in" class="rounded border p-2"><input required type="date" name="check_out" class="rounded border p-2"><input required type="number" min="1" max="{{ $room->capacity }}" name="guests" value="1" class="rounded border p-2"><input required name="guest_name" value="{{ auth()->user()->name }}" class="rounded border p-2"><input required type="email" name="guest_email" value="{{ auth()->user()->email }}" class="rounded border p-2"><button class="rounded bg-emerald-800 p-2 text-white">Book room</button></form>@else<a class="mt-4 inline-block text-emerald-800 underline" href="/login">Sign in to book</a>@endauth</article>@empty<p class="rounded-xl border bg-white p-8 text-slate-600 md:col-span-3">No rooms match. Adjust destination or dates.</p>@endforelse</section>{{ $rooms->links() }}</main></body></html>
